242	  }
243	
244	  // A manual step that does not close the unit asks nothing on its own; it
245	  // only asks something when it carries a checklist to confirm. Empty, it
246	  // is as bare a press as a roll.
247	  if (step.kind === "manual") {
248	    if (list.length > 0) return { ...bare, primary: null, needsPage: `${label} on the page`, presets: ticking };
