1	import type { Offer } from "./offer.ts";
2	
3	export interface Press {
4	  from: string;
5	  run: string;
6	  seq: number;
7	  ref: string;
8	  press: string;
9	  move?: string;
10	  answer?: Record<string, unknown>;
11	}
12	
13	export interface Verdict {
14	  ok: boolean;
15	  say?: string;
16	}
17	
18	export interface Acts {
19	  primary: () => void;
20	  move: (id: string) => void;
21	  undo: () => void;
22	  answer: (answer: Record<string, unknown>) => void;
23	  setup: (id: string) => void | Promise<void>;
24	  /** Move a tally or a dial, by a step or to a number. */
25	  tracker: (id: string, move: { by: number } | { to: number }) => void;
26	  clock: (id: string, doing: "pause" | "resume" | "stop") => void;
27	  autoRoll: (on: boolean) => void;
28	  finish: () => void;
29	}
30	
31	/**
32	 * Whether a press from outside may be taken, and taking it.
33	 *
34	 * Given everything it decides on, because this is the one place a run
35	 * can be moved by something that is not looking at it. Two rules do the
36	 * work. A press names the offer it was drawn from, so one made while
37	 * the unit was closing cannot roll into the next unit. And a press
38	 * names itself and who sent it, so two decks racing for the same button
39	 * each move it once, and one deck retried after an answer that never
40	 * arrived moves it only once.
41	 *
42	 * Not total, though: an `act` may throw, most likely a write raced by
43	 * another device. That still spends the ref and settles a verdict --
44	 * the deck is told the press failed rather than left waiting on one
45	 * that will never answer.
46	 */
47	export function takePress(press: Press, at: { seq: number; offer: Offer; seen: Map<string, Verdict> }, act: Acts): Verdict {
48	  const key = `${press.from}:${press.ref}`;
49	  const already = at.seen.get(key);
50	  if (already) return already;
51	
52	  const settle = (verdict: Verdict): Verdict => {
53	    at.seen.set(key, verdict);
54	    return verdict;
55	  };
56	
57	  if (press.seq !== at.seq) return settle({ ok: false, say: "That moved on." });
58	
59	  /**
60	   * Taking the press itself: a throw is still a press taken, not one left
61	   * hanging. In the act's own words where it threw any, because an act is
62	   * the only thing that can see why -- a list still wanting the page, say.
63	   */
64	  const take = (fn: () => void): Verdict => {
65	    try {
66	      fn();
67	      return { ok: true };
68	    } catch (e) {
69	      const said = e instanceof Error ? e.message.trim() : "";
70	      return { ok: false, say: said === "" ? "That press failed." : said };
71	    }
72	  };
73	
74	  switch (press.press) {
75	    case "primary": {
76	      if (!at.offer.primary) return settle({ ok: false, say: at.offer.needsPage ?? "There is nothing to press." });
77	      return settle(take(() => act.primary()));
78	    }
79	    case "move": {
80	      const id = press.move ?? "";
81	      if (!at.offer.moves.some((m) => m.id === id)) return settle({ ok: false, say: "That is not on offer." });
82	      return settle(take(() => act.move(id)));
83	    }
84	    case "undo": {
85	      if (!at.offer.undo) return settle({ ok: false, say: "There is nothing to take back." });
86	      return settle(take(() => act.undo()));
87	    }
88	    case "answer": {
89	      // Play on under a different setup: the page's own picker and its
90	      // "Hand it out" in one press, which is what a key on a deck is for.
91	      // It rides in the answer because that is the only field of a press
92	      // the server passes through, and it names a setup by id, so it is
93	      // checked against the offer the way a move is.
94	      const named = press.answer?.["setup"];
95	      if (typeof named === "string") {
96	        if (!at.offer.setups.some((s) => s.id === named)) return settle({ ok: false, say: "That setup is not here." });
97	        return settle(take(() => act.setup(named)));
98	      }
99	      /*
100	       * The four things on the page that are not the step: a tally or a
101	       * dial, the unit's clock, the dice setting, and the end of the run.
102	       * None of them answers what the step is asking, so each is checked
103	       * against the offer on its own and taken ahead of the presets below,
104	       * the way a setup is.
105	       */
106	      const tracker = press.answer?.["tracker"];
107	      if (typeof tracker === "string") {
108	        if (!at.offer.trackers.some((t) => t.id === tracker)) return settle({ ok: false, say: "That tracker is not here." });
109	        // How far to move it, or where to land it: a pair of − and + keys
110	        // sends `by`, a key that stands for a value sends `to`. What either
111	        // comes to against the run's own floor and ceiling is the act's to
112	        // settle, exactly as the panel's own buttons leave it to the run.
113	        const by = press.answer?.["by"];
114	        const to = press.answer?.["to"];
115	        if (typeof by === "number" && Number.isInteger(by)) return settle(take(() => act.tracker(tracker, { by })));
116	        if (typeof to === "number" && Number.isInteger(to)) return settle(take(() => act.tracker(tracker, { to })));
117	        return settle({ ok: false, say: "This run does not know that press." });
118	      }
119	      const clock = press.answer?.["clock"];
120	      if (typeof clock === "string") {
121	        const doing = press.answer?.["do"];
122	        const ticking = at.offer.clock;
123	        if (!ticking || ticking.id !== clock) return settle({ ok: false, say: "That clock is not here." });
124	        if (doing !== "pause" && doing !== "resume" && doing !== "stop")
125	          return settle({ ok: false, say: "This run does not know that press." });
126	        // Each of the three means something only from where the clock
127	        // already is. The page shows one button or the other for that
128	        // reason; a deck holding all three at once is told which it was.
129	        if (doing === "pause" && ticking.status !== "running") return settle({ ok: false, say: "That clock is not running." });
130	        if (doing === "resume" && ticking.status !== "paused") return settle({ ok: false, say: "That clock is not paused." });
131	        if (doing === "stop" && ticking.status === "done") return settle({ ok: false, say: "That clock has stopped." });
132	        return settle(take(() => act.clock(clock, doing)));
133	      }
134	      // Throwing the dice for the player is a setting rather than an
135	      // answer, so nothing here refuses it: a key that only ever sends
136	      // `true` is as good as one that toggles, and setting it to what it
137	      // already is leaves the run where it was.
138	      const auto = press.answer?.["autoRoll"];
139	      if (typeof auto === "boolean") return settle(take(() => act.autoRoll(auto)));
140	      // The end of the run, which the page offers only from its closing
141	      // step and only where the run may actually end. The offer carries
142	      // that button's own words, so a key face can say them.
143	      if (press.answer?.["finish"] === true) {
144	        if (!at.offer.ending) return settle({ ok: false, say: "The run cannot end here." });
145	        return settle(take(() => act.finish()));
146	      }
147	      // Tick everything this step waits for and press its own button. The
148	      // offer says whether there is a list to tick; the act says whether
149	      // one of its boxes is beyond a deck, and throws its own words if so.
150	      if (press.answer?.["ticks"] === "all") {
151	        if (!at.offer.presets.some((p) => p.kind === "checklist")) return settle({ ok: false, say: "The run is not asking for that." });
152	        return settle(take(() => act.answer({ ticks: "all" })));
153	      }
154	      if (!at.offer.presets.some((p) => p.kind === "declareSubject")) return settle({ ok: false, say: "The run is not asking for that." });
155	      if (String(press.answer?.["subject"] ?? "").trim() === "") return settle({ ok: false, say: "That answer was empty." });
156	      return settle(take(() => act.answer(press.answer!)));
157	    }
158	    default:
159	      return settle({ ok: false, say: "This run does not know that press." });
160	  }
161	}
